#include "native_common.hpp"
int main(int argc,char**argv){try{require(argc==3,"make_smoke_nsg synthetic_base new_index");require(!fs::exists(argv[2]),"preserve synthetic index");Fvecs base(argv[1]);require(base.n==4096&&base.d==32,"synthetic fixture only");acsg::IndexACSGFlat idx(base.d,64,faiss::METRIC_INNER_PRODUCT);std::vector<float> x(base.n*base.d);for(size_t i=0;i<base.n;++i)std::copy(base.row(i),base.row(i)+base.d,x.begin()+i*base.d);idx.storage->add(base.n,x.data());idx.ntotal=base.n;idx.acsg.ntotal=base.n;idx.is_trained=true;idx.is_built=true;idx.acsg.is_built=true;idx.acsg.enterpoint=0;idx.acsg.pheromone.assign(base.n,1);idx.acsg.weight.assign(base.n,1);idx.acsg.final_graph=std::make_shared<acsg::Graph<int32_t>>(base.n,64);for(size_t i=0;i<base.n;++i)for(int j=0;j<64;++j)idx.acsg.final_graph->at(i,j)=(i+j+1)%base.n;idx.save(argv[2]);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
